INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (1, 17, 1, 1, N'ThS.BS', N'15 năm kinh nghiệm chẩn đoán và điều trị bệnh lý tim mạch, tăng huyết áp và nội tiết tại BV Chợ Rẫy.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (2, 18, 1, 2, N'BSCKII', N'18 năm kinh nghiệm điều trị bệnh tim thiếu máu cục bộ, suy tim mạn và rối loạn lipid máu phức tạp.', NULL, N'default_doctor.png', 180000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (3, 19, 1, 3, N'ThS.BS', N'10 năm chuyên sâu bệnh lý tiêu hóa, trào ngược dạ dày thực quản, viêm loét HP và gan nhiễm mỡ.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (4, 20, 1, 4, N'BSCKI', N'9 năm kinh nghiệm điều trị viêm phế quản, hen suyễn, COPD và các bệnh lý dị ứng - miễn dịch.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (5, 21, 1, 5, N'ThS.BS', N'11 năm kinh nghiệm chuyên khoa Cơ xương khớp, thoái hóa khớp gối, viêm khớp dạng thấp và Gout.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (6, 22, 2, 6, N'BSCKII', N'17 năm phẫu thuật ngoại khoa tổng quát, xử lý chấn thương chỉnh hình và tiểu phẫu u lành da.', NULL, N'default_doctor.png', 180000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (7, 23, 2, 7, N'ThS.BS', N'13 năm kinh nghiệm phẫu thuật thoát vị đĩa đệm, chấn thương thể thao và nội soi khớp gối.', NULL, N'default_doctor.png', 160000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (8, 24, 2, 8, N'BSCKI', N'9 năm chuyên tiểu phẫu bướu bã, u mỡ, móng chọc thịt và khâu thẩm mỹ vết thương phức tạp.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (9, 25, 2, 9, N'ThS.BS', N'11 năm kinh nghiệm khám và điều trị sỏi tiết niệu, u xơ tiền liệt tuyến và nam học ngoại khoa.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (10, 26, 2, 10, N'BSCKI', N'8 năm kinh nghiệm khám bệnh lý hậu môn trực tràng, trĩ nội, trĩ ngoại và rò hậu môn.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (11, 27, 3, 11, N'BSCKI', N'10 năm công tác tại BV Nhi Đồng, chuyên sâu hô hấp, tiêu hóa và nhiễm khuẩn trẻ em.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (12, 28, 3, 12, N'ThS.BS', N'8 năm chuyên khoa Dị ứng - Miễn dịch nhi khoa, hen phế quản trẻ em và viêm da cơ địa.', NULL, N'default_doctor.png', 140000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (13, 29, 3, 13, N'BSCKI', N'11 năm kinh nghiệm chăm sóc trẻ sơ sinh, theo dõi vàng da, rối loạn tiêu hóa và biếng ăn.', NULL, N'default_doctor.png', 140000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (14, 30, 3, 14, N'ThS.BS', N'7 năm tư vấn dinh dưỡng trẻ nhỏ, tầm soát còi xương, chậm lớn và phát triển thể chất.', NULL, N'default_doctor.png', 130000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (15, 31, 3, 15, N'BSCKII', N'16 năm chuyên gia Nhi tổng quát, tầm soát tim bẩm sinh và xử trí co giật do sốt cao.', NULL, N'default_doctor.png', 160000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (16, 32, 4, 16, N'ThS.BS', N'Tốt nghiệp ThS ĐHYD TP.HCM, chuyên gia phục hình răng sứ, chỉnh nha và cấy ghép Implant.', NULL, N'default_doctor.png', 160000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (17, 33, 4, 17, N'BSCKI', N'12 năm kinh nghiệm chỉnh nha mắc cài kim loại, sứ và niềng răng trong suốt Invisalign.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (18, 34, 4, 18, N'ThS.BS', N'9 năm điều trị bệnh lý nha chu, tụt lợi, phẫu thuật cười hở lợi và làm trắng răng laser.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (19, 35, 4, 19, N'BSCKI', N'10 năm chuyên tiểu phẫu răng khôn mọc lệch ngầm bằng sóng siêu âm không sưng đau.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (20, 36, 4, 20, N'ThS.BS', N'8 năm chuyên khoa Nha khoa Trẻ em, tiền chỉnh nha và điều trị tủy răng sữa nhẹ nhàng.', NULL, N'default_doctor.png', 140000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (21, 37, 5, 21, N'BSCKI', N'14 năm kinh nghiệm quản lý thai kỳ nguy cơ cao, tầm soát tiền sản giật và dị tật thai nhi.', NULL, N'default_doctor.png', 180000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (22, 38, 5, 22, N'BSCKII', N'19 năm công tác tại BV Từ Dũ, chuyên sâu phẫu thuật nội soi phụ khoa và tầm soát ung thư.', NULL, N'default_doctor.png', 200000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (23, 39, 5, 23, N'ThS.BS', N'11 năm tư vấn hiếm muộn vô sinh, siêu âm canh noãn và điều trị hội chứng buồng trứng đa nang.', NULL, N'default_doctor.png', 170000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (24, 40, 5, 24, N'BSCKI', N'9 năm chuyên gia Siêu âm hình thái học thai 4D, đo độ mờ da gáy và kiểm tra doppler rốn.', NULL, N'default_doctor.png', 160000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (25, 41, 5, 25, N'ThS.BS', N'8 năm điều trị viêm nhiễm âm đạo mạn tính, lộ tuyến cổ tử cung và tư vấn tiền hôn nhân.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (26, 42, 6, 26, N'BSCKII', N'15 năm chuyên khoa Tai Mũi Họng, nội soi ống mềm NBI phát hiện sớm ung thư vòm họng.', NULL, N'default_doctor.png', 170000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (27, 43, 6, 27, N'ThS.BS', N'11 năm điều trị viêm xoang mũi mạn tính, polyp mũi và phẫu thuật nội soi xoang FESS.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (28, 44, 6, 28, N'BSCKI', N'10 năm chuyên khoa Tai thính học, đo thính lực đồ, điều trị viêm tai giữa và ù tai kéo dài.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (29, 45, 6, 29, N'ThS.BS', N'8 năm điều trị khàn tiếng, hạt xơ dây thanh, trào ngược họng thanh quản LPR.', NULL, N'default_doctor.png', 140000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (30, 46, 6, 30, N'BSCKI', N'12 năm chuyên Tai Mũi Họng Nhi khoa, nạo VA và cắt Amidan bằng công nghệ dao Coblator.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (31, 47, 7, 31, N'BSCKII', N'18 năm phẫu thuật Phaco điều trị đục thủy tinh thể và đặt kính nội nhãn đa tiêu sắc.', NULL, N'default_doctor.png', 180000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (32, 48, 7, 32, N'ThS.BS', N'10 năm chuyên gia Tật khúc xạ cận - loạn thị học đường, fitting kính áp tròng Ortho-K.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (33, 49, 7, 33, N'BSCKI', N'12 năm khám và điều trị bệnh võng mạc đái tháo đường, thoái hóa hoàng điểm tuổi già.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (34, 50, 7, 34, N'ThS.BS', N'8 năm điều trị Glaucoma (cườm nước), kiểm soát nhãn áp và theo dõi thị trường mắt.', NULL, N'default_doctor.png', 140000.00, N'Đang làm việc');
INSERT INTO bac_si (id, nhan_vien_id, chuyen_khoa_id, phong_kham_chinh_id, hoc_vi, kinh_nghiem, gioi_thieu, avatar, gia_kham, trang_thai_lam_viec) VALUES (35, 51, 7, 35, N'BSCKI', N'11 năm kinh nghiệm khám viêm loét giác mạc, khô mắt mạn tính và mộng thịt tái phát.', NULL, N'default_doctor.png', 150000.00, N'Đang làm việc');
