INSERT INTO thong_bao (id, tai_khoan_id, tieu_de, noi_dung, loai_thong_bao, lien_ket, da_doc, thoi_gian_tao) VALUES (1, 48, N'Tiếp nhận lịch khám thành công!', N'Lịch hẹn khám mã LH26090002 của bạn vào ngày mai lúc 09:00 tại Chuyên khoa Nội đã được bộ phận Lễ tân tiếp nhận. Vui lòng có mặt trước 15 phút tại Quầy tiếp đón.', N'Lịch hẹn', N'/patient/booking', 0, N'2026-10-22 21:38:17');
INSERT INTO thong_bao (id, tai_khoan_id, tieu_de, noi_dung, loai_thong_bao, lien_ket, da_doc, thoi_gian_tao) VALUES (2, 48, N'Hoàn thành đợt khám bệnh', N'Hồ sơ khám bệnh EMR và kết quả xét nghiệm mã PK26090001 đã có kết quả đầy đủ. Bạn có thể tra cứu và tải toa thuốc trên cổng bệnh nhân.', N'Khám bệnh', N'/patient/records', 0, N'2026-10-22 21:38:17');
INSERT INTO thong_bao (id, tai_khoan_id, tieu_de, noi_dung, loai_thong_bao, lien_ket, da_doc, thoi_gian_tao) VALUES (3, 1, N'Đăng ký ca làm việc mới', N'Nhân sự Nhân sự y tế vừa đăng ký 2 ca làm việc mới, đang chờ duyệt.', N'Lịch trực', N'/admin/staff?tab=approvals', 1, N'2026-10-31 13:02:40');
