INSERT INTO thong_bao (id, tai_khoan_id, tieu_de, noi_dung, loai_thong_bao, lien_ket, da_doc, thoi_gian_tao) VALUES (2282, 57, N'Nhắc lịch hẹn tái khám: PK2644228', N'Kính gửi Đỗ Thị Bích Ngân, quý khách có lịch tái khám theo hẹn vào ngày 2026-11-03 (Bác sĩ: BS. Phạm Hồng Nhung). Lời dặn: Không dụi tay lên mắt, rửa tay thường xuyên, đeo kính râm bảo vệ mắt khi đi ra ngoài trời nắng gió. Vui lòng đặt lịch hẹn hoặc đến phòng khám đúng hẹn.', N'Nhắc tái khám', N'/patient/records', 0, N'2026-11-03 11:59:10');
INSERT INTO thong_bao (id, tai_khoan_id, tieu_de, noi_dung, loai_thong_bao, lien_ket, da_doc, thoi_gian_tao) VALUES (2283, 157, N'Nhắc lịch hẹn tái khám: PK2644238', N'Kính gửi Phạm Thanh Thảo, quý khách có lịch tái khám theo hẹn vào ngày 2026-11-03 (Bác sĩ: BS. Phạm Thúy Hằng). Lời dặn: Tránh cúi gập người mang vác nặng, nằm đệm cứng vừa phải, tập các bài tập kéo giãn cơ lưng nhẹ nhàng. Vui lòng đặt lịch hẹn hoặc đến phòng khám đúng hẹn.', N'Nhắc tái khám', N'/patient/records', 0, N'2026-11-03 11:59:10');
INSERT INTO banner (id, tieu_de, phu_de, mo_ta, hinh_anh, link_lien_ket, text_nut, thu_tu, trang_thai, ngay_tao) VALUES (1, N'Chăm sóc bằng tài năng, y đức và sự thấu cảm', N'Tiêu chuẩn chất lượng quốc tế', N'Bệnh viện Đa khoa Quốc tế H2T Healthcare mang đến trải nghiệm khám chữa bệnh chuẩn mực với 35 bác sĩ chuyên khoa giàu kinh nghiệm và hệ thống bệnh án điện tử EMR 360°.', N'https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=1600', N'/booking', N'ĐĂNG KÝ KHÁM NGAY', 1, 1, N'2026-10-22 21:38:17');
INSERT INTO banner (id, tieu_de, phu_de, mo_ta, hinh_anh, link_lien_ket, text_nut, thu_tu, trang_thai, ngay_tao) VALUES (2, N'Đội ngũ 35 Bác sĩ chuyên khoa đầu ngành', N'Chuyên môn vững vàng', N'Hội tụ 35 bác sĩ chuyên khoa ThS.BS, BSCKII tại 7 chuyên khoa lâm sàng, tận tâm đồng hành vì sức khỏe toàn diện của gia đình bạn.', N'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=1600', N'#bac-si', N'TÌM BÁC SĨ CHUYÊN KHOA', 2, 1, N'2026-10-22 21:38:17');
INSERT INTO banner (id, tieu_de, phu_de, mo_ta, hinh_anh, link_lien_ket, text_nut, thu_tu, trang_thai, ngay_tao) VALUES (3, N'Hệ thống Bệnh án điện tử EMR 360°', N'Công nghệ y tế số 4.0', N'Tra cứu trực tuyến lịch sử khám bệnh, kết quả xét nghiệm, phim X-quang và đơn thuốc tiện lợi, bảo mật tuyệt đối.', N'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1600', N'/patient', N'CỔNG THÔNG TIN BỆNH NHÂN', 3, 1, N'2026-10-22 21:38:17');
INSERT INTO bai_viet (id, tac_gia_id, tieu_de, slug, danh_muc, tom_tat, noi_dung, hinh_anh, luot_xem, ngay_dang, trang_thai) VALUES (1, 1, N'Bệnh cảm cúm mùa giao mùa và cách phòng ngừa hiệu quả', N'benh-cam-cum-mua-giao-mua', N'Cẩm Nang Y Tế', N'Thời tiết chuyển mùa là điều kiện thuận lợi cho virus cúm phát triển. Nhận biết triệu chứng sớm và chế độ dinh dưỡng tăng cường miễn dịch là chìa khóa bảo vệ sức khỏe cả gia đình.', N'Nội dung chi tiết hướng dẫn phòng ngừa cảm cúm: giữ ấm cơ thể, rửa tay thường xuyên với xà phòng, tiêm vắc xin cúm hằng năm, bổ sung vitamin C và uống đủ nước...', N'cam-cum.jpg', 335, N'2026-10-22 21:38:17', 1);
INSERT INTO bai_viet (id, tac_gia_id, tieu_de, slug, danh_muc, tom_tat, noi_dung, hinh_anh, luot_xem, ngay_dang, trang_thai) VALUES (2, 1, N'Chăm sóc sức khỏe răng miệng cho trẻ đúng cách từ nhỏ', N'cham-soc-rang-mieng-cho-tre', N'Nhi Khoa', N'Sâu răng ở trẻ em diễn tiến rất nhanh và ảnh hưởng trực tiếp đến quá trình mọc răng vĩnh viễn sau này. Bố mẹ cần lưu ý hướng dẫn bé chải răng đúng cách và khám định kỳ 6 tháng/lần.', N'Nội dung chi tiết hướng dẫn phụ huynh lựa chọn bàn chải lông mềm, kem đánh răng phù hợp lứa tuổi...', N'rang-mieng-tre.jpg', 215, N'2026-10-22 21:38:17', 1);
INSERT INTO bai_viet (id, tac_gia_id, tieu_de, slug, danh_muc, tom_tat, noi_dung, hinh_anh, luot_xem, ngay_dang, trang_thai) VALUES (3, 1, N'Khám sức khỏe tổng quát định kỳ: Lợi ích vàng không thể bỏ qua', N'kham-suc-khoe-tong-quat-dinh-ky', N'Tin Tức Phòng Khám', N'Tầm soát sức khỏe định kỳ giúp phát hiện sớm các bệnh lý tiềm ẩn nguy hiểm như cao huyết áp, tiểu đường, gan nhiễm mỡ, gout ngay từ giai đoạn chưa có biểu hiện triệu chứng.', N'Nội dung chi tiết về các gói khám tổng quát tại H2T Healthcare...', N'kham-tong-quat.jpg', 580, N'2026-10-22 21:38:17', 1);
